before:
Complete local Go example; the app itself does not execute it:
```go
package main

import (
	"fmt"
)

func total(values ...int) int {
	sum := 0
	for _, value := range values { sum += value }
	return sum
}

func main() {
	values := []int{2, 4}
	fmt.Println(total(values...))
}

```

